//! Generates a complete, buildable Cargo project from the current pin configuration.
//!
//! Output layout for RustEmbedded (STM32/ARM):
//! ```
//! <dest>/
//! ├── .cargo/
//! │   └── config.toml      — build target + linker flags + probe-rs runner
//! ├── src/
//! │   └── main.rs          — HAL code generated by codegen.rs
//! ├── .gitignore
//! ├── build.rs             — copies memory.x to OUT_DIR
//! ├── Cargo.toml
//! └── memory.x             — flash / RAM layout for this MCU
//! ```
//!
//! Output layout for EspRust (ESP32-C3):
//! ```
//! <dest>/
//! ├── .cargo/
//! │   └── config.toml      — target + build-std + espflash runner
//! ├── src/
//! │   └── main.rs          — esp-hal code
//! ├── .gitignore
//! └── Cargo.toml
//! ```
//! No `memory.x` or `build.rs` — esp-hal 0.23 generates both `memory.x` and
//! `linkall.x` in its own OUT_DIR via its build script.  Only `-Tlinkall.x` is
//! needed in rustflags; adding a second `-Tmemory.x` redefines IROM/DROM/etc.
//! and causes a linker error ("region already defined").

use super::mcu_catalog::ToolchainKind;
use super::mcu_def::ProjectDef;
use std::{fs, io, path::Path};

// ── Public types ──────────────────────────────────────────────────────────────

/// All generated file contents for one project snapshot.
/// Cheap to build (pure string formatting); regenerated every UI frame.
pub struct ProjectFiles {
    pub main_rs: String,
    pub cargo_toml: String,
    pub cargo_config: String,
    pub memory_x: String, // empty for EspRust
    pub build_rs: String, // empty for EspRust
    pub gitignore: String,
}

// ── Public API ────────────────────────────────────────────────────────────────

/// Builds all file contents in memory without touching the filesystem.
pub fn build_project_files(
    config: &ProjectDef,
    toolchain: &ToolchainKind,
    main_rs: &str,
) -> ProjectFiles {
    match toolchain {
        ToolchainKind::RustEmbedded => ProjectFiles {
            main_rs: main_rs.to_owned(),
            cargo_toml: cargo_toml_embedded(config),
            cargo_config: cargo_config_embedded(config),
            memory_x: memory_x(config),
            build_rs: build_rs_embedded(),
            gitignore: "/target\n".to_owned(),
        },
        ToolchainKind::EspRust => ProjectFiles {
            main_rs: main_rs.to_owned(),
            cargo_toml: cargo_toml_esp(config),
            cargo_config: cargo_config_esp(config),
            // esp-hal 0.23 generates memory.x + linkall.x in its own OUT_DIR
            // via its build script.  linkall.x uses `INCLUDE memory.x` so the
            // chip memory map is already available — we must NOT supply our own
            // or the linker sees IROM/DROM/etc. defined twice.
            memory_x: String::new(),
            build_rs: String::new(),
            gitignore: "/target\n".to_owned(),
        },
        ToolchainKind::SdccC => ProjectFiles {
            main_rs: main_rs.to_owned(),
            cargo_toml: String::new(),
            cargo_config: String::new(),
            memory_x: String::new(),
            build_rs: String::new(),
            gitignore: String::new(),
        },
    }
}

/// Writes all project files into `dest` (creates the directory tree as needed).
/// `user_src_files` is a list of `(path_relative_to_src, content)` pairs.
pub fn write_project(
    dest: &Path,
    config: &ProjectDef,
    toolchain: &ToolchainKind,
    main_rs: &str,
    user_src_files: &[(String, String)],
) -> io::Result<()> {
    let files = build_project_files(config, toolchain, main_rs);

    fs::create_dir_all(dest.join("src"))?;
    fs::create_dir_all(dest.join(".cargo"))?;

    // ── Remove stale .rs files from src/ ─────────────────────────────────────
    // When the user switches between chip types (e.g. STM32 → ESP32-C3), the
    // workspace directory still contains .rs files written during the previous
    // build (e.g. src/lib.rs with `use stm32f1xx_hal`).  Those stale files are
    // not part of the new project, but `cargo check` picks them up and fails.
    //
    // Build the authoritative set of paths that SHOULD exist inside src/:
    // main.rs (always generated) + every user source file.
    let expected_in_src: std::collections::HashSet<String> = user_src_files
        .iter()
        .map(|(p, _)| p.clone())
        .chain(std::iter::once("main.rs".to_string()))
        .collect();
    remove_stale_rs(&dest.join("src"), &dest.join("src"), &expected_in_src);

    // ── Remove stale Cargo.lock ───────────────────────────────────────────────
    // If the workspace was previously used for a different chip (e.g. STM32),
    // Cargo.lock pins the old dependency versions.  Even though Cargo.toml is
    // rewritten correctly, cargo honours the lock-file and may resolve esp-hal
    // to a version that predates the `#[esp_hal::main]` proc macro.
    // Deleting the lock-file forces a fresh dependency resolution each time the
    // project is written.  Cargo's on-disk package cache means this does NOT
    // re-download crates — only re-solves the version graph.
    let _ = fs::remove_file(dest.join("Cargo.lock"));

    // Files common to all toolchains
    fs::write(dest.join("Cargo.toml"), &files.cargo_toml)?;
    fs::write(dest.join(".cargo").join("config.toml"), &files.cargo_config)?;
    fs::write(dest.join("src").join("main.rs"), &files.main_rs)?;
    fs::write(dest.join(".gitignore"), &files.gitignore)?;

    // memory.x + build.rs — only for RustEmbedded (STM32/ARM).
    //
    // For EspRust: esp-hal 0.23 generates its own complete memory.x (with
    // IROM, DROM, IRAM, DRAM, RTC_FAST) in its build-script OUT_DIR.
    // linkall.x starts with `INCLUDE "memory.x"` and searches the linker
    // -L paths in order.  If a project-level memory.x is present (from a
    // previous build or toolchain switch), it shadows esp-hal's file, causing
    // either "IROM already defined" (if -Tmemory.x is also present) or
    // missing regions (if the stale file is incomplete).
    // → Always delete stale copies first, then only write for RustEmbedded.
    let _ = fs::remove_file(dest.join("memory.x"));
    let _ = fs::remove_file(dest.join("build.rs"));

    // fs::write(dest.join("build.rs"), &files.build_rs)?;

    if !files.memory_x.is_empty() {
        fs::write(dest.join("memory.x"), &files.memory_x)?;
        fs::write(dest.join("build.rs"), &files.build_rs)?;
    }

    // User source files (same for all toolchains)
    for (rel_path, content) in user_src_files {
        let full = dest.join("src").join(rel_path);
        if let Some(parent) = full.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(full, content)?;
    }

    println!("project_gen write_project()");
    Ok(())
}

/// Walks `dir` recursively and removes every `.rs` file whose path relative to
/// `root` is **not** listed in `keep`.  Errors on individual files are silently
/// ignored — a failed removal produces no stale content (the file stays) and
/// does not abort the project write.
fn remove_stale_rs(root: &Path, dir: &Path, keep: &std::collections::HashSet<String>) {
    let Ok(entries) = fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            remove_stale_rs(root, &path, keep);
        } else if path.extension().and_then(|e| e.to_str()) == Some("rs") {
            if let Ok(rel) = path.strip_prefix(root) {
                // Normalise to forward slashes so the lookup matches on Windows
                let rel_str = rel.to_string_lossy().replace('\\', "/");
                if !keep.contains(&rel_str) {
                    let _ = fs::remove_file(&path);
                }
            }
        }
    }
}

/// Default `src/main.rs` for an ESP32-C3 project (no pin layout configured yet).
pub fn esp32c3_fresh_main_rs() -> String {
    r#"// Auto-generated by Embedded IDE
// MCU: ESP32-C3 | HAL: esp-hal

#![no_std]
#![no_main]

pub mod pins;


esp_bootloader_esp_idf::esp_app_desc!();

#[esp_hal::main]
fn main() -> ! {
    let peripherals = esp_hal::init(esp_hal::Config::default().with_cpu_clock(esp_hal::clock::CpuClock::max()));
    loop {
        // Your main loop code here.
    }
}
"#
    .to_string()
}

// ── RustEmbedded file generators ──────────────────────────────────────────────

fn cargo_toml_embedded(c: &ProjectDef) -> String {
    format!(
        "[package]\n\
         name    = \"{name}-project\"\n\
         version = \"0.1.0\"\n\
         edition = \"2021\"\n\
         \n\
         [[bin]]\n\
         name  = \"{name}-project\"\n\
         test  = false\n\
         bench = false\n\
         \n\
         [dependencies]\n\
         cortex-m    = {{ version = \"0.7\", features = [\"critical-section-single-core\"] }}\n\
         cortex-m-rt = \"0.7\"\n\
         panic-halt  = \"0.2\"\n\
         {hal}\n\
         \n\
         # Flash with:  cargo flash --chip {chip} --release\n\
         # Debug with:  cargo run   --release   (requires probe-rs in PATH)\n\
         \n\
         [profile.release]\n\
         panic         = \"abort\"\n\
         codegen-units = 1\n\
         debug         = true\n\
         lto           = true\n\
         opt-level     = \"s\"\n\
         \n\
         [profile.dev]\n\
         panic     = \"abort\"\n\
         opt-level = 1\n",
        name = c.pkg_name,
        hal = c.hal_dep,
        chip = c.probe_chip,
    )
}

fn cargo_config_embedded(c: &ProjectDef) -> String {
    format!(
        "[build]\n\
         target = \"{target}\"\n\
         \n\
         [target.{target}]\n\
         # Requires probe-rs: https://probe.rs/docs/getting-started/installation/\n\
         runner    = \"probe-rs run --chip {chip}\"\n\
         rustflags = [\n\
             \"-C\", \"link-arg=-Tlink.x\",\n\
         ]\n",
        target = c.target,
        chip = c.probe_chip,
    )
}

fn memory_x(c: &ProjectDef) -> String {
    format!(
        "/* {comment} */\n\
         MEMORY\n\
         {{\n\
             FLASH : ORIGIN = {flash_o}, LENGTH = {flash_s}\n\
             RAM   : ORIGIN = {ram_o},   LENGTH = {ram_s}\n\
         }}\n",
        comment = c.memory_comment,
        flash_o = c.flash_origin,
        flash_s = c.flash_size,
        ram_o = c.ram_origin,
        ram_s = c.ram_size,
    )
}

/// `build.rs` placed in the project root.
/// Copies `memory.x` to `OUT_DIR` so the linker script (`link.x` for ARM,
/// `linkall.x` for ESP32) can find it via the `rustc-link-search` path.
fn build_rs_embedded() -> String {
    let mut s = String::new();
    s.push_str("use std::env;\n");
    s.push_str("use std::fs::File;\n");
    s.push_str("use std::io::Write;\n");
    s.push_str("use std::path::PathBuf;\n");
    s.push_str("\n");
    s.push_str("fn main() {\n");
    s.push_str("    let out = PathBuf::from(env::var_os(\"OUT_DIR\").unwrap());\n");
    s.push_str("    File::create(out.join(\"memory.x\"))\n");
    s.push_str("        .unwrap()\n");
    s.push_str("        .write_all(include_bytes!(\"memory.x\"))\n");
    s.push_str("        .unwrap();\n");
    s.push_str("    println!(\"cargo:rustc-link-search={}\", out.display());\n");
    s.push_str("    println!(\"cargo:rerun-if-changed=memory.x\");\n");
    s.push_str("}\n");
    s
}

// ── EspRust file generators ───────────────────────────────────────────────────

fn cargo_toml_esp(c: &ProjectDef) -> String {
    format!(
        "[package]\n\
         name    = \"{name}-project\"\n\
         version = \"0.1.0\"\n\
         edition = \"2024\"\n\
         \n\
         [[bin]]\n\
         name  = \"{name}-project\"\n\
         test  = false\n\
         bench = false\n\
         \n\
         [dependencies]\n\
         esp-hal       = {{ version = \"~1.1.0\", features = [\"{chip}\"] }}\n\
         esp-println   = {{ version = \"0.13\", features = [\"{chip}\", \"log\"] }}\n\
         esp-bootloader-esp-idf = {{ version = \"0.5.0\", features = [\"{chip}\"] }}\n\
         critical-section = \"1.2.0\"\n\
         \n\
         # Flash with: espflash flash --chip {chip} --release\n\
         # Install:    cargo install espflash\n\
         \n\
         [profile.release]\n\
         codegen-units = 1\n\
         debug         = 2\n\
         lto           = \"fat\"\n\
         opt-level     = \"s\"\n\
         \n\
         [profile.dev]\n\
         opt-level     = \"s\"\n",
        name = c.pkg_name,
        chip = c.probe_chip, // "esp32c3"
    )
}

fn cargo_config_esp(c: &ProjectDef) -> String {
    format!(
        "[target.{target}]\n\
         # --ignore-app-descriptor: esp-hal bare-metal binaries do not carry an\n\
         # ESP-IDF app descriptor; espflash 4.x requires this flag to skip the\n\
         # descriptor check. Add --monitor to open the serial console after flash.\n\
         #runner = \"espflash flash --monitor --ignore-app-descriptor\"\n\
         runner = \"espflash flash --monitor --chip {chip}\"\n\
         # esp-hal 0.23 places linkall.x + memory.x in its OUT_DIR via its\n\
         # build script.  linkall.x uses `INCLUDE memory.x` internally, so\n\
         # the chip memory map (IROM, DROM, IRAM, DRAM, RTC_SLOW) is already\n\
         # present.  Only -Tlinkall.x is needed here; supplying a second\n\
         # -Tmemory.x would redefine those regions and cause a linker error.\n\
         rustflags = [\n\
            \"-C\", \"link-arg=-Tlinkall.x\",\n\
            # \"-C\", \"force-frame-pointers\",\n\
         ]\n\
         \n\
         [build]\n\
         target = \"{target}\"\n\
         \n\
         [env]\n\
         ESP_LOG = \"INFO\"\n\
         \n\
         [unstable]\n\
         build-std = [\"core\"]\n",
        target = c.target,
        chip = c.probe_chip,
    )
}
